private HttpStatus checkForConflicts(Owner owner, boolean sharesHousehold) {
    if (!sharesHousehold && isHouseholdDuplicate(owner)) {
        return HttpStatus.CONFLICT;
    }
    if (isCityAtCapacity(owner.getCity())) {
        return HttpStatus.CONFLICT;
    }
    return null;
